bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
printf 'CONTAINERS_BEGIN\n'
docker ps --format '{{.Names}}' | grep -Ei 'gate|gaybbs|createvdobot|video|telegram' | head -n 20 || true
printf 'CONTAINERS_END\n'
docker exec -i "$cid" node --input-type=module <<'NODE'
import pg from 'pg';import{readFileSync}from'node:fs';
const e=process.env;
const u=e.VIDEOBOT_DATABASE_URL_FILE?readFileSync(e.VIDEOBOT_DATABASE_URL_FILE,'utf8').trim():'postgresql://'+encodeURIComponent(e.VIDEOBOT_DB_USER)+':'+encodeURIComponent(readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim())+'@'+e.VIDEOBOT_DB_HOST+':5432/'+e.VIDEOBOT_DB_NAME;
const c=new pg.Client({connectionString:u,connectionTimeoutMillis:5000});
try{
await c.connect();
for(const [name,sql] of [
 ['LISTING','select status,count(*)::integer as n from videobot_listings group by status order by status'],
 ['POST','select status,count(*)::integer as n from videobot_post_receipts group by status order by status'],
 ['UNPOSTED',"select count(*)::integer as n from videobot_listings l where not exists (select 1 from videobot_post_receipts r where r.listing_id=l.listing_id and r.revision=l.revision and r.status='sent' and r.paid_message_id is not null)"]
]){
 const q=await c.query(sql);
 for(const row of q.rows)console.log(name+'='+JSON.stringify(row));
}
}finally{await c.end().catch(()=>{})}
NODE
